function N({registerIndicator:y,sourceValues:b,nulls:h}){const u=(l,s)=>{const t=l.length,a=new Array(t).fill(NaN);let o=0,c=0,n=0,p=0,i=0;for(let e=0;e<t;e++){if(e>=s){const r=e-s,m=l[r];Number.isFinite(m)&&(o-=r,c-=m,n-=r*m,p-=r*r,i-=1)}const f=l[e];if(Number.isFinite(f)&&(o+=e,c+=f,n+=e*f,p+=e*e,i+=1),i<2)continue;const d=i*p-o*o;d!==0&&(a[e]=(i*n-o*c)/d)}return a};y({id:"oa-jolt",name:"Acceleration, Slope of Slope (JOLT)",category:"Numerics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:2,max:5e3,step:1,tooltip:"Lookback used by each of the three least squares slope passes."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"jolt",type:"line",title:"Jolt",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,s){const t=Math.max(2,Math.floor(Number(s.period)||14)),a=b(l,s.source||"close"),o=u(a,t),c=u(o,t),n=u(c,t);return{jolt:h(n)}}})}export{N as default};
